INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('victor_kasonde', 'Victor Kasonde', 'Vic', '1947-03-12', 'M', 'Musician', 'addr_northmead_flat_1', 'Lead guitarist and vocalist, Broken String. House band at The Copperbelt Room on Cha Cha Cha Road. Radio Zambia broadcast the band twice in the past year. A third session was being negotiated at the time of death.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('grace_mwape', 'Grace Mwape', NULL, '1931-06-04', 'F', 'Club Owner', 'addr_kabulonga_house', 'Co-owner of The Copperbelt Room. Manages the club accounts. Attended Evelyn Hone College. Married to Arthur Mwape.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('arthur_mwape', 'Arthur Mwape', NULL, '1926-11-22', 'M', 'Club Owner', 'addr_kabulonga_house', 'Co-owner of The Copperbelt Room. Public-facing partner. Handles relations with musicians, press, and the licensing board. Does not manage the accounts.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('bernard_chanda', 'Bernard Chanda', NULL, '1922-08-15', 'M', 'Finance Director', 'addr_rhodes_park_1', 'Senior Director of Finance, NCCM (Nchanga Consolidated Copper Mines). Member, UNIP National Council, Lusaka Province. Drives a grey Mercedes-Benz 220.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('solomon_musonda', 'Solomon Musonda', 'Solo', '1928-04-18', 'M', 'Transport Operator', 'addr_chilenje_1', 'Owner, Musonda Transport. Three trucks on the Lusaka-Ndola corridor. Extends informal personal loans. Known to the precinct for two prior disputes, both resolved.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('patrick_kabwe', 'Patrick Kabwe', 'Pato', '1945-09-03', 'M', 'Musician', 'addr_matero_flat_1', 'Rhythm guitarist, The Copper Kings. Had a public argument with Victor Kasonde on 11 November 1974 over a disputed song composition. Witnesses present.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('agnes_lungu', 'Agnes Lungu', NULL, '1950-02-28', 'F', 'Secretary', 'addr_northmead_flat_2', 'Victor Kasonde''s girlfriend of fourteen months. Works at a legal firm on Cairo Road. Had been asking questions at the club in the days before the murder.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('chilufya_nsofu', 'Chilufya Nsofu', NULL, '1940-07-09', 'M', 'Bouncer', 'addr_chilenje_2', 'Head bouncer, The Copperbelt Room. Three years at the club. Was absent from his post between approximately 22:10 and 22:40 on the night of the murder.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('choolwe_mutale', 'Choolwe Mutale', NULL, '1943-05-14', 'M', 'Events Promoter', 'addr_woodlands_flat_1', 'Victor Kasonde''s informal booking agent. Arranged Radio Zambia session negotiations and club circuit bookings. Had a dispute with Kasonde over an unpaid commission of 40 kwacha.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('blessings_mwanza', 'Blessings Mwanza', NULL, '1946-12-01', 'F', 'Bartender', 'addr_matero_flat_2', 'Head bartender, The Copperbelt Room. Three years at the club. Witnessed the argument between Kabwe and Kasonde on 11 November. On duty the night of the murder.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('enos_simukonda', 'Enos Simukonda', NULL, '1922-03-27', 'M', 'Caretaker', 'addr_chilenje_3', 'Club caretaker and night cleaner. Found the body of Victor Kasonde in the rear alley at approximately 01:40 on 15 November 1974.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('joanna_zulu', 'Joanna Zulu', NULL, '1940-08-11', 'F', 'Recording Coordinator', 'addr_woodlands_house_1', 'Recording coordinator, Radio Zambia. Was negotiating a full studio session and possible vinyl pressing for Broken String. Met with Kasonde privately twice in the week before his death.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('elizabeth_kasonde', 'Elizabeth Kasonde', NULL, '1942-01-17', 'F', 'Schoolteacher', 'addr_kabulonga_flat', 'Victor Kasonde''s older sister. Teaches at a primary school in Kabulonga. Next of kin. Notified by DC Mwamba at 06:15 on 15 November 1974.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('emmanuel_banda', 'Emmanuel Banda', 'Manny', '1949-05-22', 'M', 'Musician', 'addr_chilenje_4', 'Bassist, Broken String. Victor Kasonde''s closest bandmate. Reported to CID on 15 November that a guitar E-string was missing from the band''s supply case. String had been present at the previous rehearsal on 12 November.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('chibesa_mwamba', 'Chibesa Mwamba', NULL, '1948-09-30', 'M', 'Police Officer', 'addr_northmead_house', 'Detective Constable, CID Lusaka. First officer to secure the crime scene at The Copperbelt Room. Took initial statements from Nsofu, Mwanza, and Simukonda.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('boyd_sikazwe', 'Boyd Sikazwe', NULL, '1936-07-14', 'M', 'Journalist', 'addr_rhodes_park_2', 'Music correspondent, Times of Zambia. Has written two profiles of Broken String, the most recent published August 1974. Was not at the club on the night of the murder.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('joseph_mwale', 'Joseph Mwale', 'Joze', '1942-03-06', 'M', 'Musician', NULL, 'Former bassist. Disappeared September 1972. Missing persons case 72/LKS/0891. Never resolved. Last known address: Chilenje. No body found, no explanation given.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('francis_bwalya', 'Francis Bwalya', NULL, '1935-11-04', 'M', 'Police Officer', 'addr_woodlands_house_2', 'Detective Inspector, CID Lusaka. Seven years in service. Handles commercial and market-related cases. Assigned to Kamwala district disputes.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('rajan_patel', 'Rajan Patel', NULL, '1930-04-19', 'M', 'Wholesaler', 'addr_kamwala_1', 'Co-owner, Patel Brothers Import Wholesale, Kamwala market. Imports dry goods, hardware, and textiles. Third-generation business.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('suresh_patel', 'Suresh Patel', NULL, '1933-08-22', 'M', 'Wholesaler', 'addr_kamwala_1', 'Co-owner, Patel Brothers Import Wholesale, Kamwala market. Handles logistics and supplier relations.');
INSERT INTO people (id, name, alias, dob, gender, occupation, address_id, notes) VALUES ('temwani_phiri', 'Temwani Phiri', NULL, '1957-05-03', 'M', 'Bar Back', 'addr_matero_flat_3', 'Bar back, The Copperbelt Room. Seventeen years old. Reported seeing a woman follow Kasonde toward the rear exit at approximately 22:10 on the night of the murder. Did not see her face clearly.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (1, 'bernard_chanda', 'grace_mwape', '1974-10-03', '18:45', 14, 'NCCM-Central', 'Chanda calls Grace Mwape from NCCM offices.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (2, 'bernard_chanda', 'grace_mwape', '1974-10-17', '19:20', 22, 'NCCM-Central', 'Chanda calls Grace Mwape from NCCM offices.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (3, 'bernard_chanda', 'grace_mwape', '1974-11-01', '12:30', 31, 'NCCM-Central', 'Chanda calls Grace Mwape from NCCM offices. Unusually long duration.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (4, 'bernard_chanda', 'grace_mwape', '1974-11-14', '15:10', 8, 'NCCM-Central', 'Chanda calls Grace Mwape on the afternoon of 14 November.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (5, 'grace_mwape', 'victor_kasonde', '1974-11-10', '10:30', 6, 'Kabulonga', 'Grace Mwape calls Victor Kasonde at his home number. Content unknown.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (6, 'victor_kasonde', 'grace_mwape', '1974-11-12', '14:00', 3, 'Northmead', 'Victor Kasonde calls The Copperbelt Room. Short call.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (7, 'victor_kasonde', 'joanna_zulu', '1974-11-11', '16:15', 18, 'Northmead', 'Victor Kasonde calls Joanna Zulu at Radio Zambia. Likely session scheduling.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (8, 'victor_kasonde', 'joanna_zulu', '1974-11-13', '17:00', 11, 'Northmead', 'Victor Kasonde calls Joanna Zulu at Radio Zambia. Second call in three days.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (9, 'choolwe_mutale', 'victor_kasonde', '1974-11-10', '09:15', 5, 'Woodlands', 'Mutale calls Kasonde. Believed to relate to the unpaid commission of K40.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (10, 'victor_kasonde', 'choolwe_mutale', '1974-11-12', '11:30', 2, 'Northmead', 'Kasonde calls Mutale. Very short call.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (11, 'elizabeth_kasonde', 'victor_kasonde', '1974-11-10', '20:00', 12, 'Kabulonga', 'Elizabeth Kasonde calls her brother. He told her he was in a complicated situation involving the club.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (12, 'victor_kasonde', 'agnes_lungu', '1974-11-13', '19:45', 9, 'Northmead', 'Victor calls Agnes Lungu. Agnes later reported the call was brief and he seemed distracted.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (13, 'solomon_musonda', NULL, '1974-11-12', '08:30', 7, 'Lusaka-Central', 'Musonda calls Livingstone Transport Co-operative from Lusaka to arrange delivery confirmation before departing.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (14, 'solomon_musonda', NULL, '1974-11-14', '09:00', 4, 'Livingstone', 'Musonda calls his Lusaka office from Livingstone exchange. Confirms on-site with trucks. Call places him in Livingstone on the day of the murder.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (15, 'grace_mwape', NULL, '1974-11-14', '11:00', NULL, 'Kabulonga', 'Outbound call from Grace Mwape. Receiver number not attributed in exchange log. Duration unrecorded.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (16, 'arthur_mwape', 'grace_mwape', '1974-11-14', '23:05', 2, 'Pamodzi-Hotel', 'Arthur Mwape calls Grace from the Pamodzi Hotel. Consistent with his statement that Grace telephoned him about the incident — exchange log records the call as initiated by Arthur.');
INSERT INTO phone_calls (id, caller_id, receiver_id, date, time, duration_min, exchange, notes) VALUES (17, NULL, 'francis_bwalya', '1972-09-28', '14:00', 3, 'Chilenje', 'Incoming call to DI Bwalya from Chilenje exchange. Three days before Mwale missing persons notice was filed. Caller not identified.');
