INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (1, 'enos_simukonda', 'chibesa_mwamba', '1974-11-15', 'The Copperbelt Room, 12 Cha Cha Cha Road', 'I finished mopping the back corridor at around half past one in the morning. When I pushed open the alley door — the one by the stage store — I nearly tripped. A man was lying face down between the bins and the wall. I called out. No movement. I ran inside and found Chilufya at the front and told him to call the police. I did not touch the body. The alley door latch was already up when I reached it. I assumed someone had left it open for air.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (2, 'chilufya_nsofu', 'chibesa_mwamba', '1974-11-15', 'The Copperbelt Room, 12 Cha Cha Cha Road', 'My post is the front entrance. I was there until around ten past ten. Then Mrs Mwape — Grace Mwape — came to me personally. She said there was a delivery man at the service gate who needed escorting out. She gave me fifty ngwee and said she would watch the front door for twenty minutes. I went to the service gate. There was no one there. I waited, then walked around to the rear alley. Nothing. I came back to my post at about twenty to eleven. Mrs Mwape was gone from the front by then. I assumed she had returned to her office.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (3, 'blessings_mwanza', 'chibesa_mwamba', '1974-11-15', 'The Copperbelt Room, 12 Cha Cha Cha Road', 'Kasonde came to the bar around nine, between sets. He seemed anxious — kept glancing toward the back corridor. He had one Mosi and went back. Later, around ten or ten past, I saw Mrs Mwape walking toward the back corridor. That is normal — the office is that way. I did not see her come back. The bar was busy. At around twenty past ten the band returned to the stage without Kasonde. Emmanuel told the room he was taking a short break. That was not normal. Kasonde never missed an entrance.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (4, 'temwani_phiri', 'chibesa_mwamba', '1974-11-15', 'The Copperbelt Room, 12 Cha Cha Cha Road', 'I was carrying empties from the rear bar to the store corridor at around ten past ten. I saw Mr Kasonde go through the internal door at the end of the corridor — the one that leads to the rear alley. A minute or two later, a woman followed him through the same door. I did not see her face. She wore a dark dress, blue or black. Medium height, not young. I thought nothing of it at the time. I assumed it was one of the owners.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (5, 'emmanuel_banda', 'chibesa_mwamba', '1974-11-15', 'CID Headquarters, Lusaka', 'Victor and I have played together for three years. He never walked off mid-set without telling me. When he did not come back for the second half I thought he had too much to drink, or a problem with his guitar. On the fifteenth, when I heard what had happened, I went straight to the equipment case. We keep spare E-strings — Victor breaks them at least once a month. There should have been four in the case. There were three. I last confirmed all four were there on the twelfth of November at our rehearsal.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (6, 'elizabeth_kasonde', 'chibesa_mwamba', '1974-11-15', '11A Leopards Hill Road, Kabulonga', 'Victor telephoned me on the tenth. He said he was in a complicated situation involving someone at the club. He would not say more. He said he was going to resolve it and I should not worry. I told him to be careful with the people he was dealing with. He could be too clever for his own good sometimes. When you told me he had been strangled, my first thought was: that is close work. Someone he trusted, or someone who got very close to him.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (7, 'agnes_lungu', 'chibesa_mwamba', '1974-11-16', 'CID Headquarters, Lusaka', 'I was at the UNZA Nice bar from about half past eight until after midnight. I was with my cousin, Priscilla Banda — she is a second-year student there. Victor and I had argued that week. He was keeping something from me. I thought at first it was another woman. Now I think it was something more serious than that. He was frightened. Victor was not the type to be frightened easily. You can speak to Priscilla.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (8, 'solomon_musonda', 'chibesa_mwamba', '1974-11-16', 'CID Headquarters, Lusaka', 'I have been in Livingstone since the twelfth. Three trucks on a southern route contract — copper fittings for the railway line. I came back on the sixteenth when I heard the news. Victor owed me five hundred kwacha — borrowed in November of last year for some equipment. He paid me back on the fourteenth. His bank transferred it while I was in Livingstone. I had half written the debt off. I had no reason to want him dead. A dead man repays nothing.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (9, 'arthur_mwape', 'chibesa_mwamba', '1974-11-16', 'CID Headquarters, Lusaka', 'I was not at the club that evening. I had dinner at the Pamodzi Hotel with clients from Kitwe — mineral rights people. Grace handles the evening operations. She always has. She telephoned me around eleven to say there had been an incident and police had been called. I drove down immediately. She told me about Kasonde in the car park. She was very composed. Grace is always composed, of course — but that night, even for her, she was very composed.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (10, 'grace_mwape', 'chibesa_mwamba', '1974-11-16', 'CID Headquarters, Lusaka', 'I was in the office from approximately half past nine reviewing accounts. I did not leave the office during that time. I spoke briefly to Chilufya in the corridor around ten — I asked him to check the service gate, which has been giving trouble. I did not go to the rear alley. I did not follow anyone. Kasonde was our house-band musician. We had a straightforward professional relationship. I have no knowledge of why anyone would wish him harm.');
INSERT INTO interviews (id, subject_id, officer_id, date, location, statement) VALUES (11, 'choolwe_mutale', 'chibesa_mwamba', '1974-11-16', 'CID Headquarters, Lusaka', 'I was at the Ridgeway Hotel restaurant from about seven until after ten. I was meeting Emmanuel Nkonde — he is promotions manager at Radio Zambia — to discuss future session arrangements for the band. He can confirm. As for Victor: yes, we had a disagreement over a commission. Forty kwacha. He had a different view of what we had agreed. It was not a large sum. I was not going to harm a man over forty kwacha.');
INSERT INTO crime_scene_reports (id, location_id, date, time, officer_id, description) VALUES (1, 'addr_copperbelt_alley', '1974-11-15', '02:10', 'chibesa_mwamba', 'Victim found lying face down between waste bins and the rear wall of the premises. Ligature mark around neck consistent with strangulation by thin wire. No signs of struggle beyond perimortem marks. Rear alley door found unlatched from inside — latch is operated from the corridor side only. Single set of fresh heel impressions in compacted dirt adjacent to body, smaller than victim''s footwear, possibly female. No weapon recovered at scene.');
INSERT INTO crime_scene_reports (id, location_id, date, time, officer_id, description) VALUES (2, 'addr_northmead_flat_1', '1974-11-15', '09:30', 'chibesa_mwamba', 'Search of victim''s residence at 14B Bwacha Road, Northmead. One-bedroom flat, no signs of disturbance. Personal papers searched. Recovered one handwritten note (evidence item 4) found inside a book on the bedroom shelf. Note reads: ''Agreed amount monthly, first of each month, until I say otherwise. If you stop I speak to Arthur.'' Unsigned. Flat otherwise unremarkable.');
INSERT INTO evidence (id, report_id, item, description, location_found) VALUES (1, 1, 'Guitar E-string', 'Single guitar E-string wire, approximately 65 centimetres, found around the victim''s neck post-mortem. Light gauge, consistent with commercial guitar strings. Identified by Emmanuel Banda as matching the type used by Broken String. One string of this type found missing from the band''s supply case — last confirmed present on 12 November.', 'Around victim''s neck, rear alley');
INSERT INTO evidence (id, report_id, item, description, location_found) VALUES (2, 1, 'Heel impression', 'Single partial heel impression in compacted dirt, adjacent to body. Approximately 7 centimetres width. Inconsistent with victim''s footwear (size 11 boot). Estimate: female shoe, size 5 to 6. Photographed. Cast not taken due to dry conditions.', 'Rear alley, adjacent to body');
INSERT INTO evidence (id, report_id, item, description, location_found) VALUES (3, 1, 'Internal door latch', 'Alley-side internal door found in unlatched position when scene was examined. Latch mechanism is operated from the corridor side only — it cannot be opened from the alley without a key. Indicates the door was opened from inside by someone with access to the back corridor.', 'Internal door, stage corridor');
INSERT INTO evidence (id, report_id, item, description, location_found) VALUES (4, 2, 'Handwritten note', 'Note reads: ''Agreed amount monthly, first of each month, until I say otherwise. If you stop I speak to Arthur.'' Unsigned. Found inside a copy of ''The African Child'' on the victim''s bedroom shelf. Handwriting analysis requested. The reference to ''Arthur'' may indicate the writer feared exposure to someone named Arthur.', 'Victim''s flat, 14B Bwacha Road, Northmead');
INSERT INTO evidence (id, report_id, item, description, location_found) VALUES (5, NULL, 'Club cash box discrepancy', 'Cash box from the club manager''s office reviewed at DC Mwamba''s request. Physical cash and ledger balance in agreement at K1,340. However, cross-reference with the club''s Standard Chartered bank statements reveals repeated unexplained withdrawals over eighteen months, totalling approximately K6,500. All withdrawals are recorded under maintenance and equipment headings. No corresponding contractor receipts found on file.', 'Club manager''s office, The Copperbelt Room');
INSERT INTO sightings (id, subject_id, location_id, date, time, witness_id, notes) VALUES (1, 'grace_mwape', 'addr_copperbelt_room', '1974-11-14', '22:10', 'temwani_phiri', 'Woman in dark dress observed following Victor Kasonde through the internal corridor door toward the rear of the club. Witness did not see her face clearly. Described as medium height, not young. Consistent with Grace Mwape''s build and attire that evening per other witness accounts.');
INSERT INTO sightings (id, subject_id, location_id, date, time, witness_id, notes) VALUES (2, 'patrick_kabwe', 'addr_ridgeway_lounge', '1974-11-14', '20:30', NULL, 'Kabwe seen at the Ridgeway Lounge bar at approximately 20:30. The Copper Kings were performing that evening. Confirmed by multiple venue staff and band members.');
INSERT INTO sightings (id, subject_id, location_id, date, time, witness_id, notes) VALUES (3, 'patrick_kabwe', 'addr_ridgeway_lounge', '1974-11-14', '23:00', NULL, 'Kabwe still present at the Ridgeway Lounge at end of the Copper Kings set, approximately 23:00. Alibi confirmed by venue staff and band members. Kabwe could not have been at The Copperbelt Room.');
INSERT INTO sightings (id, subject_id, location_id, date, time, witness_id, notes) VALUES (4, 'agnes_lungu', 'addr_unza_nice', '1974-11-14', '20:30', NULL, 'Agnes Lungu at the UNZA Nice bar from approximately 20:30. Present with her cousin, Priscilla Banda, a second-year student. Remained until after midnight. Alibi confirmed by cousin and venue staff.');
INSERT INTO sightings (id, subject_id, location_id, date, time, witness_id, notes) VALUES (5, 'choolwe_mutale', 'addr_ridgeway_lounge', '1974-11-14', '19:30', NULL, 'Choolwe Mutale at the Ridgeway Hotel restaurant from approximately 19:30 until after 22:00. Meeting with Emmanuel Nkonde, Radio Zambia Promotions. Confirmed by Nkonde and restaurant staff.');
INSERT INTO sightings (id, subject_id, location_id, date, time, witness_id, notes) VALUES (6, 'solomon_musonda', 'LIVINGSTONE', '1974-11-14', NULL, NULL, 'Musonda confirmed in Livingstone on the day of the murder. Presence verified by delivery receipts, truck driver statements, and telephone exchange records showing a call from the Livingstone exchange at 09:00.');
INSERT INTO sightings (id, subject_id, location_id, date, time, witness_id, notes) VALUES (7, 'bernard_chanda', 'addr_copperbelt_room', '1974-11-14', '18:00', 'temwani_phiri', 'Grey Mercedes-Benz 220 with plate LSK 4412 observed parked outside The Copperbelt Room at approximately 18:00. Vehicle is registered to Bernard Chanda. Chanda not seen entering the premises.');
INSERT INTO vehicles (id, owner_id, make, model, year, plate, color) VALUES (1, 'bernard_chanda', 'Mercedes-Benz', '220', 1971, 'LSK 4412', 'Grey');
INSERT INTO vehicles (id, owner_id, make, model, year, plate, color) VALUES (2, 'arthur_mwape', 'Peugeot', '504', 1973, 'LB 7831', 'White');
INSERT INTO vehicles (id, owner_id, make, model, year, plate, color) VALUES (3, 'solomon_musonda', 'Bedford', 'TK', 1969, 'LNB 0012', 'Blue');
INSERT INTO vehicles (id, owner_id, make, model, year, plate, color) VALUES (4, 'solomon_musonda', 'Bedford', 'TK', 1968, 'LNB 0045', 'Green');
INSERT INTO vehicles (id, owner_id, make, model, year, plate, color) VALUES (5, 'solomon_musonda', 'Bedford', 'TK', 1970, 'LNB 0089', 'Red');
INSERT INTO vehicles (id, owner_id, make, model, year, plate, color) VALUES (6, 'francis_bwalya', 'Land Rover', 'Series III', 1972, 'GP 5517', 'Brown');
