INSERT INTO club_bookings (id, venue, performer_id, date, set_start, set_end, fee) VALUES (3, 'The Copperbelt Room, 12 Cha Cha Cha Road', 'victor_kasonde', '1974-10-31', '20:00', '23:30', 35);
INSERT INTO club_bookings (id, venue, performer_id, date, set_start, set_end, fee) VALUES (4, 'The Copperbelt Room, 12 Cha Cha Cha Road', 'victor_kasonde', '1974-11-07', '20:00', '23:30', 35);
INSERT INTO newspaper_archive (id, date, headline, section, author_id, body) VALUES (1, '1974-11-16', 'Musician Found Dead at City Centre Club', 'News', 'boyd_sikazwe', 'A 27-year-old musician was found dead in the rear alley of The Copperbelt Room on Cha Cha Cha Road in the early hours of Friday morning. Victor Kasonde, lead guitarist of popular Lusaka group Broken String, was discovered by club staff at approximately 01:40. Police have confirmed the death is being treated as suspicious. Detective Constable Chibesa Mwamba of the CID confirmed that enquiries are ongoing. The club has been temporarily closed. No arrests have been made.');
INSERT INTO newspaper_archive (id, date, headline, section, author_id, body) VALUES (2, '1974-08-22', 'Broken String: The Sound of Copper Town', 'Arts and Culture', 'boyd_sikazwe', 'In a first-floor rehearsal room off Cairo Road, four young men are building something. Broken String — led by guitarist Victor Kasonde, 27, from Northmead — plays a style that fuses Zambian township rhythms with electric lines that would not be out of place in Lagos or Kinshasa. ''We are making Zambian music for Zambia,'' says Kasonde. ''Not copying anyone.'' Radio Zambia has broadcast the group twice in the past twelve months. A third session, and possibly a vinyl pressing, is under negotiation. Broken String performs regularly at The Copperbelt Room on Cha Cha Cha Road, Thursday and Saturday evenings.');
INSERT INTO newspaper_archive (id, date, headline, section, author_id, body) VALUES (3, '1972-10-04', 'Missing: Joseph Mwale, Musician, Last Seen Chilenje', 'Notices', NULL, 'The family of Joseph Mwale, 30, requests any information regarding his whereabouts. Mr Mwale, known as Joze, was a bass guitarist with several Lusaka musical groups. He was last seen in the Chilenje area on or around 20 September 1972. Described as tall, of medium build, with close-cropped hair. Anyone with information should contact CID Lusaka or the family directly. Case reference: 72/LKS/0891.');
INSERT INTO newspaper_archive (id, date, headline, section, author_id, body) VALUES (4, '1974-11-18', 'No Arrest in Cha Cha Cha Road Murder', 'News', 'boyd_sikazwe', 'Three days after the death of musician Victor Kasonde at The Copperbelt Room, CID Lusaka has confirmed no arrests have been made. A spokesperson said enquiries are continuing and the investigation is active. Kasonde, the lead guitarist of Broken String, was found strangled in the club''s rear alley in the early hours of 15 November. Bandmates and family have paid tribute. The club remains temporarily closed.');
INSERT INTO precinct_logs (id, date, officer_id, entry_type, notes) VALUES (1, '1974-11-15', 'chibesa_mwamba', 'shift_log', '01:52 — Called to The Copperbelt Room, 12 Cha Cha Cha Road. Body of male found in rear alley by club caretaker. Victim identified as Victor Kasonde, 14B Bwacha Road, Northmead. Scene secured. Initial statements taken from E. Simukonda (caretaker), B. Mwanza (bartender), T. Phiri (bar back), C. Nsofu (bouncer). Evidence log opened. CID notified at 02:20.');
INSERT INTO precinct_logs (id, date, officer_id, entry_type, notes) VALUES (2, '1974-11-15', 'chibesa_mwamba', 'case_note', '06:15 — Next of kin notified. Elizabeth Kasonde, 11A Leopards Hill Road, Kabulonga. 09:30 — Search of victim''s flat, 14B Bwacha Road, Northmead. Handwritten note recovered, logged as evidence item 4. Note references an agreed monthly payment and a person named Arthur. Flat otherwise undisturbed.');
INSERT INTO precinct_logs (id, date, officer_id, entry_type, notes) VALUES (3, '1972-10-04', 'francis_bwalya', 'missing_persons', 'Case 72/LKS/0891. Joseph Mwale, male, 30, musician, last known address Chilenje. Last seen approximately 20 September 1972. No physical evidence of foul play at last known address. Subject known to travel between Lusaka, Ndola, and Livingstone for musical engagements. Enquiries initiated with Ndola and Livingstone divisions.');
INSERT INTO precinct_logs (id, date, officer_id, entry_type, notes) VALUES (4, '1972-12-01', 'francis_bwalya', 'missing_persons', 'Case 72/LKS/0891 — progress note. No trace of Mwale found. Ndola and Livingstone divisions returned negative enquiries. No known associates have heard from him. Chilenje address vacated. File remains open.');
INSERT INTO precinct_logs (id, date, officer_id, entry_type, notes) VALUES (5, '1973-03-15', 'francis_bwalya', 'admin', 'Case 72/LKS/0891 — Mwale. Supervisor review completed. Insufficient grounds for continued active investigation. No evidence of crime. Subject may have departed voluntarily. Classification changed to inactive. File retained on record.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (1, 'arthur_mwape', 'grace_mwape', 'spouse', 'Married 1956. Co-owners of The Copperbelt Room. Arthur is the public-facing partner; Grace manages the accounts.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (2, 'grace_mwape', 'bernard_chanda', 'romantic', 'Extramarital affair. Duration unknown, at least several months. Victor Kasonde was aware of the relationship.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (3, 'grace_mwape', 'victor_kasonde', 'employer', 'Mwape employed Kasonde as house-band musician. Kasonde was also blackmailing her at K50 per month over the embezzlement and the affair.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (4, 'victor_kasonde', 'agnes_lungu', 'romantic', 'Relationship of fourteen months. Lungu was unaware of the blackmail arrangement or the specifics of what Kasonde had discovered.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (5, 'victor_kasonde', 'choolwe_mutale', 'business', 'Mutale acted as Kasonde''s informal booking agent. Unpaid commission of K40 was in dispute at the time of Kasonde''s death.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (6, 'solomon_musonda', 'victor_kasonde', 'creditor', 'Musonda extended a K500 personal loan to Kasonde in November 1973. Kasonde repaid in full on 14 November 1974, the day of his murder.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (7, 'victor_kasonde', 'patrick_kabwe', 'rival', 'Public dispute on 11 November 1974 over a composition Kabwe alleged Kasonde had stolen. Multiple witnesses present. Dispute was ongoing at time of death.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (8, 'victor_kasonde', 'emmanuel_banda', 'colleague', 'Bandmates in Broken String for three years. Close personal friendship. Emmanuel was the first to report the missing E-string to CID.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (9, 'victor_kasonde', 'joanna_zulu', 'professional', 'Zulu was coordinating a Radio Zambia studio session and potential vinyl pressing for Broken String. Met Kasonde privately twice in the week before his death.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (10, 'chilufya_nsofu', 'grace_mwape', 'employee', 'Nsofu employed as head bouncer at The Copperbelt Room. On the night of the murder, Grace Mwape paid him fifty ngwee to vacate the front entrance on a false pretext.');
INSERT INTO relationships (id, person_a_id, person_b_id, type, notes) VALUES (11, 'francis_bwalya', 'rajan_patel', 'acquaintance', 'Bwalya handles commercial disputes in Kamwala district. Patel Brothers has been subject to multiple market disputes within Bwalya''s caseload. Contact extends beyond official channels.');
INSERT INTO confidential_notes (id, date, author_badge, classification, content) VALUES (1, '1974-02-15', 'DI/CID/0047', 'RESTRICTED', 'Received visit from R. Patel (Patel Brothers Import Wholesale, Kamwala, Stand 44) regarding ongoing market dispute with the Zambia Co-operative Federation. Matter resolved informally. Payment of K200 received as a consultancy gratuity. No formal record to be filed.');
INSERT INTO confidential_notes (id, date, author_badge, classification, content) VALUES (2, '1974-06-03', 'DI/CID/0047', 'RESTRICTED', 'Second informal settlement — Patel Brothers matter. K300 received. R. Patel states ZCF dispute fully resolved. No further action required. Memorandum for personal file only.');
INSERT INTO confidential_notes (id, date, author_badge, classification, content) VALUES (3, '1974-10-18', 'DI/CID/0047', 'RESTRICTED', 'Patel Brothers — further consultancy gratuity, K200. New matter: ZCF inspectors threatening licence review of Stand 44. Advised R. Patel to file application with the district council rather than engage inspectors directly. My involvement in this matter is strictly advisory in nature.');
INSERT INTO confidential_notes (id, date, author_badge, classification, content) VALUES (4, '1974-11-07', 'DI/CID/0047', 'RESTRICTED', 'Meeting with S. Patel at the Lusaka Club, 18:00. He raised the possibility of a more formal ongoing arrangement. I told him I could not');
